window.BFM = window.BFM || {};
window.BFM.generatedContent = "<a class=\"skip-link\" href=\"#main-content\">本文へスキップ</a>\n<div class=\"reading-progress\" role=\"progressbar\" aria-label=\"Part 2の学習進捗\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\"><span id=\"reading-progress-bar\" aria-hidden=\"true\"></span></div>\n\n<header class=\"site-header\" id=\"top\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"BFM Japan Part 2 トップへ\">\n      <span class=\"brand-mark\" aria-hidden=\"true\">B</span>\n      <span><strong>BFM Japan</strong><small>OFFENSIVE BFM / 02</small></span>\n    </a>\n    <button class=\"menu-toggle\" id=\"menu-toggle\" type=\"button\" aria-expanded=\"false\" aria-controls=\"global-nav\" aria-label=\"メニューを開く\">\n      <span></span><span></span><span></span>\n    </button>\n    <nav class=\"global-nav\" id=\"global-nav\" aria-label=\"メインナビゲーション\">\n      <a href=\"index.html#overview\">BFM入門</a>\n      <a href=\"#offensive-overview\">Offensive BFM</a>\n      <a href=\"#defensive-next\">Defensive BFM</a>\n    </nav>\n    <details class=\"mission-index-menu\" id=\"mission-index-menu\">\n      <summary class=\"toc-toggle\" aria-label=\"Part 2の学習目次を開く\">\n        <span class=\"toc-toggle-title\">目次</span>\n      </summary>\n      <nav class=\"mission-index-panel\" id=\"mission-index-panel\" aria-label=\"Offensive BFMの学習目次\">\n        <div class=\"mission-index-heading\">\n          <div><span>PART 2 / MISSION INDEX</span><strong>Offensive BFM</strong></div>\n          <button class=\"toc-close\" id=\"toc-close\" type=\"button\" aria-label=\"学習目次を閉じる\"><span aria-hidden=\"true\"></span></button>\n        </div>\n        <ol class=\"mission-index-list\">\n          <li><a href=\"#offensive-overview\"><span>01</span>Offensive BFMとは</a></li>\n          <li><a href=\"#offensive-geometry\"><span>02</span>攻撃位置を読む</a></li>\n          <li><a href=\"#offensive-entry\"><span>03</span>Attack Window</a></li>\n          <li><a href=\"#offensive-yoyos\"><span>04</span>High / Low Yo-Yo</a></li>\n            <li><a href=\"#offensive-overshoot\"><span>05</span>Lag Displacement Roll</a></li>\n          <li><a href=\"#offensive-responses\"><span>06</span>Defender Response</a></li>\n          <li><a href=\"#high-aspect\"><span>07</span>High-Aspect BFM</a></li>\n          <li><a href=\"#offensive-recap\"><span>08</span>要点整理</a></li>\n          <li><a href=\"#offensive-quiz\"><span>09</span>確認問題</a></li>\n          <li><a href=\"#offensive-references\"><span>10</span>参考資料・出典</a></li>\n          <li><a href=\"#defensive-next\"><span>11</span>Next Part</a></li>\n        </ol>\n        <div class=\"index-progress\" role=\"progressbar\" aria-label=\"Part 2の学習進捗\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\">\n          <span>PART 2 PROGRESS</span>\n          <strong id=\"progress-percent\">0%</strong>\n        </div>\n      </nav>\n    </details>\n  </header>\n\n<main id=\"main-content\">\n  <section class=\"hero offensive-course-hero\" id=\"part-two-hero\" aria-labelledby=\"offensive-hero-title\">\n        <div class=\"hero-grid\"></div>\n        <div class=\"hero-copy\">\n          <p class=\"kicker hero-part-label\">PART 2:</p>\n          <h1 id=\"offensive-hero-title\"><span class=\"hero-title-main\"><span class=\"hero-title-phrase\">Offensive BFM</span></span></h1>\n          <p class=\"hero-definition\">\n            Part 1で学んだ位置関係とEnergyを攻撃側の判断へつなげ、相手のTurn Circle上で優位を保ちながら<strong>安定した攻撃機会を作る考え方</strong>を学びます\n          </p>\n          <div class=\"hero-actions\">\n            <a class=\"button button-primary\" href=\"#offensive-overview\">Part 2を始める <span aria-hidden=\"true\">↘</span></a>\n            <a class=\"button button-quiet\" href=\"index.html#overview\">Part 1を確認する</a>\n          </div>\n        </div>\n        <aside class=\"hero-briefing\" aria-labelledby=\"offensive-hero-briefing-title\">\n          <header><span>WHAT YOU LEARN</span><strong id=\"offensive-hero-briefing-title\">3 DECISIONS</strong></header>\n          <dl>\n            <div><dt><span>01</span>Assess</dt><dd>RAC・LOSR・相対Energyから現在の攻撃位置を読む</dd></div>\n            <div><dt><span>02</span>Control</dt><dd>Entryと追跡を選び、Control Zoneへつながる関係を作る</dd></div>\n            <div><dt><span>03</span>Reassess</dt><dd>防御反応や中立化を認識し、次の判断へ切り替える</dd></div>\n          </dl>\n          <p><span>PART 2 GOAL</span> Energyの余裕を保って攻撃側の優位を維持し、管理できる攻撃機会へ進むことを目指します。</p>\n        </aside>\n        <div class=\"scroll-cue\" aria-hidden=\"true\"><span></span>SCROLL TO MISSION 01</div>\n      </section>\n\n  <div class=\"page-shell\" id=\"page-shell\">\n    <article class=\"learning-content\">\n      <section class=\"mission-sequence part-two-mission\" id=\"offensive-overview\" data-section=\"Offensive BFMとは\" aria-labelledby=\"offensive-overview-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>01</span></p>\n              <p class=\"mission-reveal-title\">Offensive BFMとは</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"offensive-overview-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"offensive-overview-title\"><span class=\"module-title-number lesson-number\">01:</span><span class=\"module-title-text lesson-title-text\">Offensive BFMとは</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>Part 2で学ぶ3つの判断と、Offensive BFMで目指す状態を説明できる。</p>\n          </header>\n          <p class=\"lead-copy\">原資料では、Offensive BFMを<strong>優位な位置から相手のTurn Circle上へ進み、Energyの余裕を保ちながらControl Zoneを経て、管理できる攻撃機会へ移るための連続的な問題解決</strong>として扱っています。最初の機会が成立しないときも攻撃側の優位を維持し、状況が中立化したらHigh-Aspect BFMへ判断を切り替えます。このPartでは、その流れをフライトシミュレーター向けの位置関係と判断に絞って学びます。<a class=\"source-marker\" href=\"#offensive-ref-1\" aria-label=\"参考資料1へ\">[1]</a><a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">WHAT YOU LEARN</p>\n            <h3>このPartで学ぶ3つの判断</h3>\n            <div class=\"comparison-cards three-up card-grid offensive-goals\">\n              <article class=\"content-card\"><span class=\"compare-tag\">01 ASSESS</span><h3>攻撃位置を読む</h3><p>Range・Angles・Closure、LOSR、相対Energyを組み合わせ、現在の位置と次に起こる変化を読みます。</p></article>\n              <article class=\"content-card\"><span class=\"compare-tag\">02 CONTROL</span><h3>位置関係を整える</h3><p>Turn Circle Entry、追跡曲線、Yo-Yo、Lag Displacement Rollを、RACとEnergyの問題に応じて選びます。</p></article>\n              <article class=\"content-card\"><span class=\"compare-tag\">03 REASSESS</span><h3>変化後の関係を読む</h3><p>防御側のRedefinition、Overshoot、中立化を認識し、古い追跡を続けず次の関係へ判断を更新します。</p></article>\n            </div>\n          </div>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">PART 2 OBJECTIVE</p>\n            <h3>目指す状態までの流れ</h3>\n            <ol class=\"fundamentals-path logic-flow offensive-objective-flow\">\n              <li><span>01</span><div><h3>現在の関係を把握する</h3><p>RAC、LOSR、相対Energyから、使えるTurning Roomと今の問題を確認します。</p></div></li>\n              <li><span>02</span><div><h3>攻撃側の優位を維持する</h3><p>相手のTurn Circle上へ進み、Overshootを避けながらEnergyと後方位置を保ちます。</p></div></li>\n              <li><span>03</span><div><h3>管理できる機会を作る</h3><p>Control ZoneへつながるRange・Angles・Closureを整え、安定した攻撃機会へ進みます。</p></div></li>\n              <li><span>04</span><div><h3>関係の変化に対応する</h3><p>機会が成立しなければ優位を維持して組み直し、中立化したらHigh-Aspect BFMとして読み直します。</p></div></li>\n            </ol>\n            <p class=\"term-note\">Control Zoneは最終目的ではなく、攻撃機会へ移るための途中の位置です。技を一度実行することではなく、選択後も優位とEnergyが残る関係を作ることを重視します。<a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n          </div>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">PART 1 PREREQUISITE</p>\n            <h3>共通概念は短く振り返る</h3>\n            <p>Range・Angles・Closure、追跡、Energy、運動面の定義はPart 1と共通です。ここでは繰り返さず、攻撃側がそれらをどう組み合わせて読むかに集中します。</p>\n            <div class=\"comparison-cards four-up card-grid review-map\">\n              <article class=\"content-card\"><h3>位置関係</h3><p><a href=\"index.html#geometry\">Part 1 Mission 06</a></p></article>\n              <article class=\"content-card\"><h3>追跡曲線</h3><p><a href=\"index.html#pursuit\">Part 1 Mission 08</a></p></article>\n              <article class=\"content-card\"><h3>Energy</h3><p><a href=\"index.html#energy\">Part 1 Mission 04</a></p></article>\n              <article class=\"content-card\"><h3>運動面</h3><p><a href=\"index.html#plane-motion\">Part 1 Mission 12</a></p></article>\n            </div>\n          </div>\n          <div class=\"bridge-note callout callout-bridge\"><span>SCOPE</span><p>このPartでは、機種固有のG値・速度・操縦入力・武器操作・訓練設定値を扱いません。公開資料に共通する位置関係と判断の考え方に範囲を絞ります。<a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>Part 2では、位置を読み、関係を整え、結果を再評価する順番を学びます。目標は技の再現ではなく、Energyの余裕を保ちながら攻撃側の優位を維持し、管理できる攻撃機会へ進むことです。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence part-two-mission\" id=\"offensive-geometry\" data-section=\"攻撃位置を読む\" aria-labelledby=\"offensive-geometry-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>02</span></p>\n              <p class=\"mission-reveal-title\">攻撃位置を読む</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"offensive-geometry-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"offensive-geometry-title\"><span class=\"module-title-number lesson-number\">02:</span><span class=\"module-title-text lesson-title-text\">攻撃位置を読む</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>有利・不利を単一の角度で決めず、位置・変化・利用できる空間から読む。</p>\n          </header>\n          <p class=\"lead-copy\">攻撃位置は「相手の後ろにいる」だけでは評価できません。Part 1で学んだRAC（Range・Angles・Closure）を一つのCross-checkとして読み、<strong>自機の余裕</strong>と<strong>相手の動き</strong>を同時に確かめます。</p>\n          <div class=\"comparison-cards two-up card-grid\">\n            <article class=\"content-card\"><span class=\"compare-tag\">OWNSHIP</span><h3>自機の余裕を読む</h3><p>速度と高度だけでなく、現在の旋回を続けたあとにEnergyと選択肢が残るかを見ます。</p><dl><div><dt>現在</dt><dd>機首位置・Energy・運動面</dd></div><div><dt>次</dt><dd>選択後に残る旋回と再配置の余裕</dd></div></dl></article>\n            <article class=\"content-card\"><span class=\"compare-tag\">OPPONENT</span><h3>相手の変化を読む</h3><p>相手の位置と行動を、RACとLOSRの変化から読みます。現在位置だけで判断を止めません。</p><dl><div><dt>現在</dt><dd>Range・Angles・Closure</dd></div><div><dt>変化</dt><dd>LOSR・飛行経路・運動面</dd></div></dl></article>\n          </div>\n          <p class=\"term-note\"><strong>LOSR（Line of Sight Rate）</strong>は、視界の中で相手へ向く視線方向が動く速さです。方向と変化を見ることで、相手が次にどこへ進むかを考える手掛かりになります。<a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">TURNING ROOM</p>\n            <h3>共有できる空間と、片方だけが使える空間</h3>\n            <div class=\"comparison-cards two-up card-grid\">\n              <article class=\"content-card\"><p class=\"term-en\">Shared Turning Room</p><p class=\"term-ja\">双方が利用できる空間</p><p>通常のTurning Roomは相手も使えます。空間を増やすほど、自分だけでなく相手の選択肢も増える場合があります。</p></article>\n              <article class=\"content-card\"><p class=\"term-en\">Exclusive-use Turning Room</p><p class=\"term-ja\">片方だけがすぐ使える空間</p><p>2機の位置・高度・旋回円のずれから生まれる例外的な空間です。存在だけで優位は確定せず、入ったあとのRACまで確認します。</p></article>\n            </div>\n            <p class=\"term-note\"><a href=\"index.html#turn-circle\">Turning Roomの基本定義はPart 1 Mission 07</a>で確認できます。ここでは「誰が使えるか」という違いだけを扱います。<a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n            <div class=\"table-wrap\">\n              <table>\n                <caption>攻撃位置を読む5つの問い</caption>\n                <thead><tr><th>見るもの</th><th>自分への問い</th><th>見落としたときの問題</th></tr></thead>\n                <tbody>\n                  <tr><th>自機の余裕</th><td>次の選択後もEnergyと旋回余裕が残るか</td><td>一時的な機首位置だけを優先する</td></tr>\n                  <tr><th>Range / Angles</th><td>距離と双方の向きはどう組み合わさっているか</td><td>見かけの後方位置だけで有利と誤認する</td></tr>\n                  <tr><th>Closure</th><td>距離はどの速さで変化しているか</td><td>Overshootを遅れて認識する</td></tr>\n                  <tr><th>LOSR</th><td>相手へ向く視線方向はどう動いているか</td><td>相手の新しい飛行経路を見落とす</td></tr>\n                  <tr><th>Turning Room</th><td>その空間は双方が使えるか</td><td>相手へ再配置の余地を渡す</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n          <div class=\"bridge-note callout callout-bridge\"><span>FIGHT REDEFINITION</span><p><strong>Fight Redefinition</strong>は、相手の反転や運動面の変更により、それまでの追跡計画を続けられなくなる変化です。以前の答えを引き継がず、自機の余裕と相手の動きを読み直します。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>攻撃位置はRange・Angles・Closure・Turning Roomの組み合わせです。相手の機動で関係が変わったら、その場で評価を更新します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence part-two-mission\" id=\"offensive-entry\" data-section=\"Attack Window\" aria-labelledby=\"offensive-entry-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>03</span></p>\n              <p class=\"mission-reveal-title\">Attack Window</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"offensive-entry-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"offensive-entry-title\"><span class=\"module-title-number lesson-number\">03:</span><span class=\"module-title-text lesson-title-text\">Attack Window</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>Turn Circleへ入るタイミングを、早い・適切・遅いの3状態で比較する。</p>\n          </header>\n          <p class=\"lead-copy\">相手が旋回を始めるとTurn Circleが生まれます。攻撃側は、単に内側へ急ぐのではなく、<strong>RACを管理できる時点で旋回関係へ入る</strong>必要があります。進入の違いは、次の3状態を横に並べると見分けやすくなります。</p>\n          <div class=\"turn-circle-learning-flow offensive-entry-flow\">\n            <article class=\"turn-circle-stage\">\n              <header class=\"turn-circle-stage-header\"><p class=\"turn-circle-stage-marker\"><span>TIMING</span><strong>01</strong><small>EARLY</small></p><div class=\"topic-heading\"><h3>早すぎる進入</h3><p>関係が整う前に内側へ進みます。距離が急に詰まり、飛行経路の交差とReversal opportunityを招きやすくなります。</p></div></header>\n            </article>\n            <article class=\"turn-circle-stage\">\n              <header class=\"turn-circle-stage-header\"><p class=\"turn-circle-stage-marker\"><span>TIMING</span><strong>02</strong><small>CONTROLLED</small></p><div class=\"topic-heading\"><h3>管理できる進入</h3><p>RACを同時に保ちます。必要ならLagへ戻れる余裕を残し、Control Zoneへ関係をつなげます。</p></div></header>\n            </article>\n            <article class=\"turn-circle-stage\">\n              <header class=\"turn-circle-stage-header\"><p class=\"turn-circle-stage-marker\"><span>TIMING</span><strong>03</strong><small>LATE</small></p><div class=\"topic-heading\"><h3>遅すぎる進入</h3><p>旋回円の中心や運動面のずれが広がります。Rangeが開き、相手へ機首を向け直すまでの時間も延びます。</p></div></header>\n            </article>\n          </div>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">ENTRY READING</p>\n            <h3>観察から進入判断まで</h3>\n            <ol class=\"fundamentals-path logic-flow entry-reading-flow\">\n              <li><span>01</span><div><h3>見かけの動きを観察する</h3><p>LOSRやAspectの増え方がどう変わるかを見ます。固定の一点ではなく、変化そのものを手掛かりにします。</p></div></li>\n              <li><span>02</span><div><h3>RACを読み直す</h3><p>Rangeの余裕、双方の向き、Closureを同時に確認します。一つだけ整っていても進入条件とは決めません。</p></div></li>\n              <li><span>03</span><div><h3>次の追跡を残して入る</h3><p>進入後もLagへ戻れるかを考えます。選択肢が消えるなら、まだ管理できる入口ではありません。</p></div></li>\n            </ol>\n            <p class=\"term-note\">この観察順は、Turn Circleへ入る視覚的な手掛かりとBFM Cross-checkを初心者向けにまとめたものです。機種固有の数値や操作手順は使いません。<a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n          </div>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">ATTACK WINDOW ENTRY</p>\n            <h3>3条件が重なる入口</h3>\n            <div class=\"comparison-cards three-up card-grid\">\n              <article class=\"content-card\"><span class=\"compare-tag\">RANGE</span><h3>距離の余裕</h3><p>旋回中に詰まりすぎず、次の追跡選択を残せる距離です。</p></article>\n              <article class=\"content-card\"><span class=\"compare-tag\">ANGLES</span><h3>向きの関係</h3><p>相手のTurn Circleと自分の飛行経路が、安定した追跡へつながる関係です。</p></article>\n              <article class=\"content-card\"><span class=\"compare-tag\">CLOSURE</span><h3>接近の管理</h3><p>相手へ近づきながらも、Overshootへ急速に進まない接近傾向です。</p></article>\n            </div>\n            <p class=\"term-note\"><strong>Attack Window</strong>の基本は<a href=\"index.html#turn-circle\">Part 1 Mission 07</a>で説明しています。このMissionでは、固定された箱ではなく「RACを管理できる進入条件」として比較します。<a class=\"source-marker\" href=\"#offensive-ref-3\" aria-label=\"参考資料3へ\">[3]</a></p>\n          </div>\n          <div class=\"comparison-cards three-up card-grid term-support-grid\">\n            <article class=\"content-card\"><p class=\"term-en\">Reversal opportunity</p><p class=\"term-ja\">防御側が関係を作り直せる機会</p><p>接近や飛行経路の交差により、防御側が旋回方向を変えて中立化や役割逆転を狙える余地です。<a href=\"index.html#overshoot\">Part 1の説明</a></p></article>\n            <article class=\"content-card\"><p class=\"term-en\">Control Zone</p><p class=\"term-ja\">RACを管理しやすい後方領域</p><p>固定された終点ではありません。相手の機動へ反応できる余裕を保つ途中の領域です。<a href=\"index.html#turn-circle\">Part 1の説明</a></p></article>\n            <article class=\"content-card\"><p class=\"term-en\">Misaligned Turn Circles</p><p class=\"term-ja\">旋回円がずれた状態</p><p>2機の旋回円の中心や運動面がずれています。同じ方向へ旋回していても起こります。<a href=\"index.html#alignment\">Part 1の説明</a></p></article>\n          </div>\n          <div class=\"warning-box callout callout-warning\"><span>注意</span><p>「早く旋回を始めるほど有利」とは限りません。早すぎても遅すぎても、攻撃位置は不安定になります。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>Turn Circle Entryはタイミングの問題です。RACが管理できる入口を選び、次の追跡を残します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence part-two-mission\" id=\"offensive-yoyos\" data-section=\"High / Low Yo-Yo\" aria-labelledby=\"offensive-yoyos-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>04</span></p>\n              <p class=\"mission-reveal-title\">High / Low Yo-Yo</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"offensive-yoyos-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"offensive-yoyos-title\"><span class=\"module-title-number lesson-number\">04:</span><span class=\"module-title-text lesson-title-text\">High / Low Yo-Yo</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>2つのYo-Yoを、Closureとエネルギーの交換方向で選び分ける。</p>\n          </header>\n          <p class=\"lead-copy\">Yo-Yoは、相手の運動面から一時的に外れ、空間とEnergyの交換でRACを調整する考え方です。同一面内の追跡だけでは解きにくいときに検討します。HighとLowは、<strong>今の問題と期待する変化</strong>を横に並べて比べます。<a class=\"source-marker\" href=\"#offensive-ref-1\" aria-label=\"参考資料1へ\">[1]</a></p>\n          <div class=\"comparison-cards two-up card-grid yoyo-comparison\">\n            <article class=\"content-card\"><p class=\"term-en\">High Yo-Yo</p><p class=\"term-ja\">Closureが大きいときの調整</p><p>速度の一部を高度へ移し、相手と同じ運動面から外れます。飛行経路に余裕を作り、後方関係を整え直します。</p><dl><div><dt>現れている問題</dt><dd>Rangeが急に縮み、Overshootへ近づく</dd></div><div><dt>Energyの交換</dt><dd>速度から高度へ移す</dd></div><div><dt>期待する変化</dt><dd>Closureを弱め、Lagへ戻れる余裕を作る</dd></div><div><dt>再確認</dt><dd>離れすぎず、相手に機動を強いる位置関係が残るか</dd></div></dl></article>\n            <article class=\"content-card\"><p class=\"term-en\">Low Yo-Yo</p><p class=\"term-ja\">Rangeが残るときの調整</p><p>高度の一部を速度へ移し、相手と異なる運動面を使います。Lag側に残りすぎた距離を縮めます。</p><dl><div><dt>現れている問題</dt><dd>Rangeが縮まず、攻撃機会が遠ざかる</dd></div><div><dt>Energyの交換</dt><dd>高度から速度へ移す</dd></div><div><dt>期待する変化</dt><dd>Closureを増やし、Rangeを管理域へ戻す</dd></div><div><dt>再確認</dt><dd>接近が増えすぎず、高度の余裕が残るか</dd></div></dl></article>\n          </div>\n          <div class=\"reference-figure-grid\">\n            <figure class=\"reference-figure\">\n              <div class=\"reference-image-canvas\"><img src=\"assets/reference-usn-high-yo-yo.png\" alt=\"攻撃機が目標の旋回面より上へ移動し、再び後方へ戻るHigh Yo-Yoを側面図と上面図で示した米海軍の教育図\" loading=\"lazy\"></div>\n              <figcaption class=\"compact-citation\"><a class=\"source-marker\" href=\"#offensive-ref-4\" aria-label=\"参考資料4へ\">[4]</a></figcaption>\n            </figure>\n            <figure class=\"reference-figure\">\n              <div class=\"reference-image-canvas\"><img src=\"assets/reference-usn-low-yo-yo.png\" alt=\"攻撃機が目標の旋回面より下へ移動し、距離を詰めて再び上方へ戻るLow Yo-Yoを示した米海軍の教育図\" loading=\"lazy\"></div>\n              <figcaption class=\"compact-citation\"><a class=\"source-marker\" href=\"#offensive-ref-4\" aria-label=\"参考資料4へ\">[4]</a></figcaption>\n            </figure>\n          </div>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">DECISION LOGIC</p>\n            <h3>技名ではなく問題から選ぶ</h3>\n            <ol class=\"fundamentals-path logic-flow yoyo-decision-flow\">\n              <li><span>01</span><div><h3>問題を特定する</h3><p>Closureが大きいのか、Rangeが残っているのかを分けます。判断できないときはRACへ戻ります。</p></div></li>\n              <li><span>02</span><div><h3>Energyの交換方向を選ぶ</h3><p>接近を弱めるならHigh側、距離を詰めるならLow側を考えます。名前だけで選びません。</p></div></li>\n              <li><span>03</span><div><h3>結果を再評価する</h3><p>RAC、Energy、高度の余裕を確認します。問題が変わったら同じ調整を続けません。</p></div></li>\n            </ol>\n          </div>\n          <p class=\"term-note\"><strong>In-plane</strong>は同じ運動面内、<strong>Lag</strong>は相手の後方へ機首を置く追跡です。基本定義は<a href=\"index.html#plane-motion\">Plane of Motion</a>と<a href=\"index.html#pursuit\">Pursuit Curves</a>で確認できます。</p>\n          <div class=\"warning-box callout callout-warning\"><span>注意</span><p>High Yo-Yoは万能なOvershoot回避ではありません。Low Yo-Yoも単純な近道ではありません。どちらもEnergyと空間を使うため、選択後のRACを必ず再評価します。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>HighはClosureを抑え、LowはRangeを詰めます。現在の問題と逆方向の調整を選ばないことが重要です。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence part-two-mission\" id=\"offensive-overshoot\" data-section=\"Lag Displacement Roll\" aria-labelledby=\"offensive-overshoot-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>05</span></p>\n              <p class=\"mission-reveal-title\">Lag Displacement Roll</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"offensive-overshoot-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"offensive-overshoot-title\"><span class=\"module-title-number lesson-number\">05:</span><span class=\"module-title-text lesson-title-text\">Lag Displacement Roll</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>Lag Displacement Rollを使う状況と、再配置後に読み直す項目を説明できる。</p>\n          </header>\n          <p class=\"lead-copy\"><a href=\"index.html#overshoot\">Overshootの基本定義はPart 1 Mission 09</a>で確認できます。ここでは定義を繰り返さず、<strong>発生前に管理する段階</strong>と<strong>発生後に関係を読み直す段階</strong>を分けます。</p>\n          <div class=\"comparison-cards two-up card-grid\">\n            <article class=\"content-card\"><span class=\"compare-tag\">BEFORE</span><h3>発生前</h3><p>Closureが増え、相手の飛行経路へ近づいています。まだ後方優位を保てるため、早い段階でLag側の余裕を作ります。</p><dl><div><dt>目的</dt><dd>飛行経路を越える前にRACを整える</dd></div><div><dt>判断</dt><dd>最小限の調整で後方関係を残す</dd></div></dl></article>\n            <article class=\"content-card\"><span class=\"compare-tag\">AFTER</span><h3>発生後</h3><p>飛行経路の交差や相手の反転が始まっています。以前の攻撃優位を前提にせず、役割逆転の可能性を読みます。</p><dl><div><dt>目的</dt><dd>新しい相対位置を判定する</dd></div><div><dt>判断</dt><dd>同じ追跡を続けず旋回関係を読み直す</dd></div></dl></article>\n          </div>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">LAG DISPLACEMENT ROLL</p>\n            <h3>旋回面をずらして後方へ再配置する</h3>\n            <p><strong>In-close Overshoot</strong>は、近距離で有利な後方位置を通り越しかける状態です。Lag Displacement Rollは相手の運動面をそのままなぞらず、ずらした経路で後方関係を作り直します。</p>\n            <dl class=\"force-definitions lag-displacement-terms\">\n              <div><dt>Lag<small>後方へ残す</small></dt><dd>相手の現在位置ではなく後方へ機首関係を置き、Closureを抑える考え方です。</dd></div>\n              <div><dt>Displacement<small>位置をずらす</small></dt><dd>相手と同じ旋回面をなぞらず、別の経路を使って飛行経路の長さと位置を変えます。</dd></div>\n              <div><dt>Roll<small>運動面を移す</small></dt><dd>相手の運動面に対する上下・左右の関係を変え、後方へ戻る空間を作ります。</dd></div>\n            </dl>\n            <div class=\"comparison-cards two-up card-grid\">\n              <article class=\"content-card\"><p class=\"term-en\">High Yo-Yo</p><p class=\"term-ja\">比較的小さな経路調整</p><p>後方関係がまだ管理でき、主な問題がClosureなら検討します。</p><dl><div><dt>発生段階</dt><dd>Overshootの余裕がまだ残る</dd></div><div><dt>位置変更</dt><dd>高度側へ経路を広げる</dd></div><div><dt>狙う結果</dt><dd>Closureを弱めてLagへ戻る</dd></div></dl></article>\n              <article class=\"content-card\"><p class=\"term-en\">Lag Displacement Roll</p><p class=\"term-ja\">より大きな位置のずらし</p><p>In-close Overshootが進み、同じ運動面では後方へ戻りにくいときに検討します。</p><dl><div><dt>発生段階</dt><dd>飛行経路の交差が近い</dd></div><div><dt>位置変更</dt><dd>運動面をずらして別の経路を作る</dd></div><div><dt>狙う結果</dt><dd>管理できるRACで後方へ再配置する</dd></div></dl></article>\n            </div>\n            <ol class=\"fundamentals-path logic-flow overshoot-response-flow\">\n              <li><span>01</span><div><h3>交差の兆候を読む</h3><p>Range、Closure、双方の飛行経路を見ます。In-close Flight-Path Overshootが進んでいるかを判断します。</p></div></li>\n              <li><span>02</span><div><h3>必要な位置変更を比べる</h3><p>通常のLagやHigh Yo-Yoで解決できるなら、そちらを優先します。後方へ戻れないときに、より大きなDisplacementを考えます。</p></div></li>\n              <li><span>03</span><div><h3>ずらした経路を作る</h3><p>相手の運動面をそのまま追わず、自分の飛行経路を長くします。Closureを抑えながら後方へ戻る空間を作ります。</p></div></li>\n              <li><span>04</span><div><h3>管理できる関係へ戻る</h3><p>再配置後のRange、Angles、Closureを読みます。相手との位置関係が安定しなければ、技が終わったとは判断しません。</p></div></li>\n            </ol>\n            <div class=\"comparison-cards three-up card-grid lag-displacement-checks\">\n              <article class=\"content-card\"><span class=\"compare-tag\">RANGE</span><h3>近すぎないか</h3><p>再配置後もRangeが詰まったままなら、役割逆転の危険は残っています。</p></article>\n              <article class=\"content-card\"><span class=\"compare-tag\">ANGLES</span><h3>後方関係へ戻れたか</h3><p>見かけ上後ろにいても、飛行経路が再び交差するなら安定したLagではありません。</p></article>\n              <article class=\"content-card\"><span class=\"compare-tag\">CLOSURE</span><h3>接近を管理できるか</h3><p>Closureが弱まり、次の追跡を選べる余裕が残ったかを確認します。</p></article>\n            </div>\n            <p class=\"term-note\">Lag Displacement Rollは固定された操作手順ではありません。High Yo-Yoより大きく運動面をずらし、管理可能なRACへ戻す考え方として扱います。具体的な入力や角度は、機体とEnergyで変わります。<a class=\"source-marker\" href=\"#offensive-ref-1\" aria-label=\"参考資料1へ\">[1]</a><a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n          </div>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">AFTER THE OVERSHOOT</p>\n            <h3>Scissorsは狙う技ではなく、発生した状態として読む</h3>\n            <p>攻撃側が相手を追い越し、相手が反転するとScissorsへ移る場合があります。これは攻撃優位が崩れた警告です。<strong>Role reversal</strong>は、追う側と追われる側の位置的な役割が入れ替わることを指します。</p>\n            <div class=\"comparison-cards two-up card-grid\">\n              <article class=\"content-card\"><p class=\"term-en\">Flat Scissors</p><p class=\"term-ja\">同じ面で反転が続く</p><p>水平に近い同一面内で、飛行経路の交差と反転が繰り返されます。</p><dl><div><dt>主に見るもの</dt><dd>前後位置・Energy・進行方向へ進む距離</dd></div><div><dt>変化の特徴</dt><dd>左右の反転で役割が入れ替わりやすい</dd></div></dl></article>\n              <article class=\"content-card\"><p class=\"term-en\">Rolling Scissors</p><p class=\"term-ja\">立体的な交差が続く</p><p>水平と垂直の両方向で飛行経路が交差し、螺旋状の関係になります。</p><dl><div><dt>主に見るもの</dt><dd>上下・前後位置・相対Energy</dd></div><div><dt>変化の特徴</dt><dd>単純なOne／Two Circleへ固定できない</dd></div></dl></article>\n            </div>\n            <p class=\"term-note\"><strong>Downrange travel</strong>は、旋回中も元の進行方向へどれだけ先へ進むかを表します。低速だけで優位を決めず、2機の前後位置と飛行経路の交差を合わせて読みます。</p>\n            <figure class=\"reference-figure reference-figure-wide\">\n              <div class=\"reference-image-canvas\"><img src=\"assets/reference-usn-rolling-scissors.png\" alt=\"2機が螺旋状に旋回しながら水平・垂直方向のOvershootを繰り返すRolling Scissorsを示した米海軍の教育図\" loading=\"lazy\"></div>\n              <figcaption class=\"compact-citation\"><a class=\"source-marker\" href=\"#offensive-ref-4\" aria-label=\"参考資料4へ\">[4]</a></figcaption>\n            </figure>\n          </div>\n          <div class=\"warning-box callout callout-warning\"><span>注意</span><p>「より遅く飛べばScissorsで有利」とは限りません。Energy、失速余裕、Downrange travelを見ます。さらに、2機の前後位置と飛行経路の交差を合わせて評価します。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>Overshootの兆候を早く読み、まず小さなLag調整を考えます。Scissorsへ入った時点では、攻撃優位が崩れている可能性を認識します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence part-two-mission\" id=\"offensive-responses\" data-section=\"Defender Response\" aria-labelledby=\"offensive-responses-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>06</span></p>\n              <p class=\"mission-reveal-title\">Defender Response</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"offensive-responses-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"offensive-responses-title\"><span class=\"module-title-number lesson-number\">06:</span><span class=\"module-title-text lesson-title-text\">Defender Response</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>Ditch FollowとRadius Defense Followを区別し、追従前に読み直す項目を説明できる。</p>\n          </header>\n          <p class=\"lead-copy\">防御側は、攻撃側の追跡をそのまま受け入れるとは限りません。運動面・旋回方向・高度が変われば、Control Zoneも移ります。攻撃側は相手の経路をなぞらず、<strong>変化が始まった手掛かりと、その後のRAC</strong>を読みます。</p>\n          <div class=\"comparison-cards three-up card-grid response-comparison\">\n            <article class=\"content-card\"><span class=\"compare-tag\">PLANE CHANGE</span><h3>運動面の変更</h3><p class=\"term-ja\">Ditch</p><p>相手がNose-low側へ運動面を変え、攻撃機会とControl Zoneの位置を動かします。</p><dl><div><dt>関係への影響</dt><dd>上下方向のずれとClosureが変わる</dd></div><div><dt>読み直す問い</dt><dd>そのまま追うと飛行経路を越えないか</dd></div></dl></article>\n            <article class=\"content-card\"><span class=\"compare-tag\">RADIUS CHANGE</span><h3>旋回半径を使う防御</h3><p class=\"term-ja\">Radius Defense</p><p>相手が旋回半径を小さくする方向へ関係を変え、攻撃側が得ていた角度を減らそうとします。</p><dl><div><dt>関係への影響</dt><dd>旋回円と飛行経路の交差位置が変わる</dd></div><div><dt>読み直す問い</dt><dd>以前の追跡線を続けても後方へ戻れるか</dd></div></dl></article>\n            <article class=\"content-card\"><span class=\"compare-tag\">DIRECTION CHANGE</span><h3>旋回方向の反転</h3><p class=\"term-ja\">Reversal</p><p>相手が旋回方向を変え、攻撃側の飛行経路との関係を一度に変えます。</p><dl><div><dt>関係への影響</dt><dd>中立化やRole reversalの可能性が生まれる</dd></div><div><dt>読み直す問い</dt><dd>Lagへ戻る余裕と後方位置が残るか</dd></div></dl></article>\n          </div>\n          <p class=\"term-note\">DitchとRadius Defenseは提供テキストで使われる呼称です。ここでは固定された操作ではなく、相手が作る<strong>運動面の変更</strong>と<strong>旋回半径の変更</strong>として整理します。<a class=\"source-marker\" href=\"#offensive-ref-1\" aria-label=\"参考資料1へ\">[1]</a></p>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">FOLLOW OPTIONS</p>\n            <h3>防御反応に応じて追跡を組み直す</h3>\n            <p>ここでいう<strong>Follow</strong>は、相手の飛行経路をそのままなぞることではありません。Point of Departureから新しい経路を予測し、移動したControl Zoneへつながる関係を作り直すことです。</p>\n            <div class=\"comparison-cards two-up card-grid response-follow-comparison\">\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">DITCH FOLLOW</span>\n                <h3>運動面の変更を追う</h3>\n                <p>相手がNose-low側へ運動面を変え、Control Zoneを上方・後方へ移したときに考えます。</p>\n                <dl>\n                  <div><dt>最初に見るもの</dt><dd>元の運動面を離れたPoint of Departure</dd></div>\n                  <div><dt>追跡の目的</dt><dd>相手の経路をなぞらず、高度とEnergyの余裕を残して再配置する</dd></div>\n                  <div><dt>期待する結果</dt><dd>ClosureとAnglesを整え、新しいControl Zoneへつなぐ</dd></div>\n                  <div><dt>失敗の兆候</dt><dd>飛行経路の交差が進む、またはLagに残りすぎて機首関係を戻せない</dd></div>\n                </dl>\n              </article>\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">RADIUS DEFENSE FOLLOW</span>\n                <h3>旋回半径の変更を追う</h3>\n                <p>相手が斜め下方向へ関係を変え、Energyを使ってTurn Radiusを小さくしたときに考えます。</p>\n                <dl>\n                  <div><dt>最初に見るもの</dt><dd>旋回円が変わり始めたPoint of Redefinition</dd></div>\n                  <div><dt>追跡の目的</dt><dd>早く内側へ入らず、RangeとEnergyの余裕を作って新しい旋回円へ戻る</dd></div>\n                  <div><dt>期待する結果</dt><dd>安定したLOSRを保ち、後方の位置的優位を残す</dd></div>\n                  <div><dt>失敗の兆候</dt><dd>早い再進入によるFlight-Path Overshoot、または離れすぎによる機会の遅れ</dd></div>\n                </dl>\n              </article>\n            </div>\n            <p class=\"term-note\">Ditch Followは<strong>運動面の移動</strong>、Radius Defense Followは<strong>旋回半径の変化</strong>への対応です。どちらも技名だけで選ばず、Point of Departure、RAC、Energyから判断します。<a class=\"source-marker\" href=\"#offensive-ref-1\" aria-label=\"参考資料1へ\">[1]</a></p>\n          </div>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">RESPONSE LOGIC</p>\n            <h3>どちらのFollowでも使う4段階</h3>\n            <ol class=\"fundamentals-path logic-flow response-questions\">\n              <li><span>01</span><div><h3>IDENTIFY：防御反応を分ける</h3><p>主な変化が運動面ならDitch、旋回半径ならRadius Defenseとして読みます。Point of Departureも確認します。</p></div></li>\n              <li><span>02</span><div><h3>PREDICT：新しい交差を予測する</h3><p>相手をそのまま追った場合のRange、Closure、飛行経路の交差を考えます。</p></div></li>\n              <li><span>03</span><div><h3>REPOSITION：余裕を作って戻る</h3><p>相手の軌跡をなぞらず、RangeとEnergyを残して新しい旋回関係へ再配置します。</p></div></li>\n              <li><span>04</span><div><h3>REASSESS：RACを読み直す</h3><p>安定したLOSR、後方位置、Control Zoneへのつながりを確認します。関係が再び変われば01へ戻ります。</p></div></li>\n            </ol>\n          </div>\n          <div class=\"comparison-cards two-up card-grid term-support-grid\">\n            <article class=\"content-card\"><p class=\"term-en\">Fight Redefinition</p><p class=\"term-ja\">それまでの追跡計画を続けられない変化</p><p>運動面や旋回関係が変わり、以前の答えを前提にできなくなった状態です。</p></article>\n            <article class=\"content-card\"><p class=\"term-en\">Point of Departure</p><p class=\"term-ja\">元の関係から離れ始めた手掛かり</p><p>固定座標ではありません。相手の新しい経路を予測し始める視覚的な手掛かりです。</p></article>\n          </div>\n          <p class=\"term-note\"><strong>Role reversal</strong>は、追う側と追われる側が入れ替わる攻守逆転です。単なる旋回方向の変更とは分けて考えます。Fight RedefinitionとPoint of Departureは訓練課程で扱われる用語です。<a class=\"source-marker\" href=\"#offensive-ref-3\" aria-label=\"参考資料3へ\">[3]</a></p>\n          <div class=\"warning-box callout callout-warning\"><span>注意</span><p>相手がNose-lowへ動いたからといって、同じ経路を直ちに追うとは限りません。高度余裕とEnergyを含めて判断します。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>相手がFight Redefinitionを起こしたら、以前の追跡選択はいったん無効です。Point of Departure、RAC、Energyを読み直します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence part-two-mission\" id=\"high-aspect\" data-section=\"High-Aspect BFM\" aria-labelledby=\"high-aspect-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>07</span></p>\n              <p class=\"mission-reveal-title\">High-Aspect BFM</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"high-aspect-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"high-aspect-title\"><span class=\"module-title-number lesson-number\">07:</span><span class=\"module-title-text lesson-title-text\">High-Aspect BFM</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>相対EnergyからCircle flowの仮説を立て、上下方向の組み合わせに応じて判断を更新できる。</p>\n          </header>\n\n          <p class=\"lead-copy\"><strong>High-Aspect BFM</strong>は、2機が互いの前方側に位置し、高いAspectで接近する関係を扱います。<strong>Merge</strong>は、2機が近い位置ですれ違う局面です。以前の攻撃優位を前提にできない状態を、この講座では<strong>Neutralized（中立化）</strong>と呼びます。High-Aspect BFMは変化が速く、固定された一つの展開にはなりません。<a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n\n          <dl class=\"force-definitions high-aspect-terms\">\n            <div>\n              <dt>Flow<small>旋回の流れ</small></dt>\n              <dd>Merge後に形成されるOne‑CircleまたはTwo‑Circleと、上下方向の相対的な流れです。双方の飛行経路によって決まります。</dd>\n            </div>\n            <div>\n              <dt>Lead Turn<small>すれ違う前の旋回</small></dt>\n              <dd>Merge後の角度を小さくするために、すれ違う前から旋回を始める考え方です。成立は相手の経路にも左右されます。</dd>\n            </div>\n            <div>\n              <dt>Game plan<small>Merge前の仮説</small></dt>\n              <dd>予想するFlowと、その予想を変更する条件を先に整理したものです。Merge後の事実を見て更新します。</dd>\n            </div>\n          </dl>\n\n          <div class=\"bridge-note callout callout-bridge\">\n            <span>PART 1 CONNECTION</span>\n            <p><a href=\"index.html#circle-fight\">One‑Circle / Two‑Circle</a>の定義と、<a href=\"index.html#energy\">Energy</a>・<a href=\"index.html#geometry\">Geometry</a>・<a href=\"index.html#turn-circle\">Turning Room</a>の基礎はPart 1で確認できます。ここでは、それらを中立化後の判断へつなげます。</p>\n          </div>\n\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">FIRST CROSS-CHECK</p>\n            <h3>4つの軸を同時に読む</h3>\n            <div class=\"comparison-cards four-up card-grid high-aspect-reads\">\n              <article class=\"content-card\"><span class=\"compare-tag\">01</span><h3>Relative Energy</h3><p>速度と高度だけでなく、相手と比べて次の旋回を続ける余裕があるかを見ます。</p></article>\n              <article class=\"content-card\"><span class=\"compare-tag\">02</span><h3>Geometry</h3><p>両機の向き、Aspect、飛行経路の交差が、Mergeまでにどう変わるかを見ます。</p></article>\n              <article class=\"content-card\"><span class=\"compare-tag\">03</span><h3>Turning Room</h3><p>双方が使える空間か、片方だけがすぐに使える空間かを区別します。</p></article>\n              <article class=\"content-card\"><span class=\"compare-tag\">04</span><h3>Altitude Margin</h3><p>上下方向を使った後も、安全な高度余裕と次の選択肢が残るかを見ます。</p></article>\n            </div>\n            <p class=\"term-note\">High-Aspectでは、Turning Roomの多くを双方が利用できます。片方だけが直ちに利用できるExclusive-use Turning Roomは例外として捉えます。垂直の間隔も、高度余裕を保って使える場合に初めてTurning Roomになります。<a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n          </div>\n\n          <figure class=\"reference-figure reference-figure-wide\">\n            <div class=\"reference-image-canvas reference-image-tall\"><img src=\"assets/reference-usn-circle-flow.png\" alt=\"上段のOne‑Circleと下段のTwo‑Circleで、2機が作る旋回空間の違いを比較した米海軍の教育図\" loading=\"lazy\"></div>\n            <figcaption class=\"compact-citation\"><a class=\"source-marker\" href=\"#offensive-ref-4\" aria-label=\"参考資料4へ\">[4]</a></figcaption>\n          </figure>\n\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">CIRCLE RELATION</p>\n            <h3>One‑CircleとTwo‑Circleを比べる</h3>\n            <p>これは旋回関係の比較です。どちらか一方が単独で選ぶボタンではありません。Merge前後の双方の飛行経路から形成されます。</p>\n            <div class=\"comparison-cards two-up card-grid high-aspect-circle-compare\">\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">ONE‑CIRCLE</span>\n                <h3>一つの旋回空間を共有する</h3>\n                <p>小さいTurn Radiusと、早い機首方向の変化を重視するFlowです。</p>\n                <dl>\n                  <div><dt>Game planにしやすい状況</dt><dd>相手の方が高Energyで、長いRate Fightを避けたい</dd></div>\n                  <div><dt>自機側の強み</dt><dd>小さいTurn Radiusや低速域の扱いやすさ</dd></div>\n                  <div><dt>狙う変化</dt><dd>短い時間で機首関係を作り、相手を前方へ動かす</dd></div>\n                  <div><dt>注意</dt><dd>単に速度を落とすことが目的ではなく、次の機動余裕を残す</dd></div>\n                </dl>\n              </article>\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">TWO‑CIRCLE</span>\n                <h3>別々の旋回円を作る</h3>\n                <p>持続Turn Rateと、時間をかけた角度変化を重視するFlowです。</p>\n                <dl>\n                  <div><dt>Game planにしやすい状況</dt><dd>自分に相対Energyの余裕があり、持続旋回へ使える</dd></div>\n                  <div><dt>自機側の強み</dt><dd>高い持続Turn RateとEnergyを保つ余裕</dd></div>\n                  <div><dt>狙う変化</dt><dd>旋回を続けながら、少しずつ機首方向の優位を作る</dd></div>\n                  <div><dt>注意</dt><dd>空間と高度の余裕がなくなれば、Rate Fightを続けられない</dd></div>\n                </dl>\n              </article>\n            </div>\n            <p class=\"term-note\">これはMerge前に置く<strong>Game plan</strong>です。実際のFlowは双方の飛行経路で決まります。相手がこちらへ旋回すればTwo‑Circle、反対側へ旋回すればOne‑Circleが形成されます。相手の選択が予想と違えば、計画を切り替えます。<a class=\"source-marker\" href=\"#offensive-ref-1\" aria-label=\"参考資料1へ\">[1]</a><a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n          </div>\n\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">VERTICAL / ENERGY AXIS</p>\n            <h3>上下方向の選択を比べる</h3>\n            <p>Nose-high・Level・Nose-lowは、One‑Circle / Two‑Circleとは別の比較軸です。旋回関係と上下方向を分けて読むと、判断の理由が明確になります。</p>\n            <div class=\"comparison-cards three-up card-grid high-aspect-vertical-compare\">\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">NOSE‑HIGH</span>\n                <h3>速度を高度へ移す</h3>\n                <p>垂直の空間を使い、飛行経路を変える選択です。</p>\n                <p>上昇後の速度余裕と、相手が作る位置関係を読み直します。</p>\n              </article>\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">LEVEL</span>\n                <h3>高度を大きく変えない</h3>\n                <p>相手の変化を短く観察し、既存のEnergyを保つ選択になり得ます。</p>\n                <p>判断の保留を続けると、使える空間を相手へ渡しやすくなります。</p>\n              </article>\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">NOSE‑LOW</span>\n                <h3>高度を速度へ移す</h3>\n                <p>速度と飛行経路を変え、下方の空間を使う選択です。</p>\n                <p>高度余裕と、増えた速度がClosureへ与える影響を読み直します。</p>\n              </article>\n            </div>\n          </div>\n\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">VERTICAL MERGE MATCHUPS</p>\n            <h3>上下方向の組み合わせを4パターンで読む</h3>\n            <p>次の4パターンは、提供テキストの考え方を初心者向けに整理したものです。高度だけで勝敗を決めず、相対Energy・Turning Room・高度余裕を合わせて読みます。</p>\n            <div class=\"comparison-cards two-up card-grid high-aspect-merge-matchups\">\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">BOTH NOSE‑HIGH</span>\n                <h3>双方が上へ向かう</h3>\n                <p>低い位置からMergeした側は、下から上へ使える旋回空間を確保しやすくなります。</p>\n                <dl><div><dt>起こりやすい変化</dt><dd>Energyを保てれば、先に旋回率を作って機首方向を変えやすい</dd></div><div><dt>再確認</dt><dd>上昇後の速度と、頂点を越えた後の余裕</dd></div></dl>\n              </article>\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">BOTH NOSE‑LOW</span>\n                <h3>双方が下へ向かう</h3>\n                <p>高い位置から始めた側は、速度へ交換できる高度を多く持っています。</p>\n                <dl><div><dt>起こりやすい変化</dt><dd>高度を使いすぎなければ、2回目のMergeでEnergy優位を残しやすい</dd></div><div><dt>再確認</dt><dd>増えたClosureと、下方に残る高度余裕</dd></div></dl>\n              </article>\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">YOU HIGH / OPPONENT LOW</span>\n                <h3>自分が上、相手が下</h3>\n                <p>上下へ分かれることで、相手とは異なるEnergy交換になります。</p>\n                <dl><div><dt>起こりやすい変化</dt><dd>自分は瞬間旋回率を作りやすく、先に機首方向の優位を得られる場合がある</dd></div><div><dt>再確認</dt><dd>相手の加速と、次のHigh-to-Low Mergeでの相対Energy</dd></div></dl>\n              </article>\n              <article class=\"content-card\">\n                <span class=\"compare-tag\">YOU LOW / OPPONENT HIGH</span>\n                <h3>自分が下、相手が上</h3>\n                <p>相手が上側で角度を作りやすく、自分は不利になりやすい組み合わせです。</p>\n                <dl><div><dt>優先すること</dt><dd>高度低下を増やしすぎず、使えるTurning Roomを維持する</dd></div><div><dt>再確認</dt><dd>下方の余裕と、相手が上から作る機首方向の変化</dd></div></dl>\n              </article>\n            </div>\n            <p class=\"term-note\">ここで示すのは最初に現れやすい傾向です。機体特性、開始速度、実際の高度差、双方の旋回方向で結果は変わります。上下の選択をした後も、Circle flowと相対Energyを読み直します。<a class=\"source-marker\" href=\"#offensive-ref-1\" aria-label=\"参考資料1へ\">[1]</a><a class=\"source-marker\" href=\"#offensive-ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n          </div>\n\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">MERGE DECISION FLOW</p>\n            <h3>Merge前の仮説をMerge後に更新する</h3>\n            <ol class=\"fundamentals-path logic-flow high-aspect-decision-flow\">\n              <li><span>01</span><div><h3>関係を読む</h3><p>Merge前に、相対Energy・Geometry・Turning Room・高度余裕を確認します。</p></div></li>\n              <li><span>02</span><div><h3>Game planを置く</h3><p>予想するFlowと、Lead Turnを含む考え方を仮説として整理します。変更する条件も決めます。</p></div></li>\n              <li><span>03</span><div><h3>実際の動きを観察する</h3><p>Mergeで、双方の飛行経路と機首位置が予想どおりかを確認します。</p></div></li>\n              <li><span>04</span><div><h3>Flowを更新する</h3><p>One‑Circle / Two‑Circleと上下方向を分けて読みます。予想と違えば、古いGame planを捨てます。</p></div></li>\n              <li><span>05</span><div><h3>次の余裕を再確認する</h3><p>選択後の相対Energy・Turning Room・高度余裕を読み、再び01へ戻ります。</p></div></li>\n            </ol>\n          </div>\n\n          <div class=\"warning-box callout callout-warning\"><span>固定ルールにしない</span><p>「Rate型なら必ずTwo‑Circle」とは限りません。相手のEnergyだけでOne‑Circleを決めることもできません。機体、初期位置、相対Energy、Geometry、高度余裕を合わせて判断します。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>High-Aspectへ移ったら、以前の攻撃優位という前提を外します。旋回関係と上下方向を別々に読みます。Merge後の事実に合わせてGame planを更新します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence part-two-mission\" id=\"offensive-recap\" data-section=\"要点整理\" aria-labelledby=\"offensive-recap-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>08</span></p>\n              <p class=\"mission-reveal-title\">要点整理</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"offensive-recap-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"offensive-recap-title\"><span class=\"module-title-number lesson-number\">08:</span><span class=\"module-title-text lesson-title-text\">要点整理</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>Offensive BFMの判断を一つの流れで説明し、不明な章へ戻れる。</p>\n          </header>\n          <p class=\"lead-copy\">Offensive BFMは「この状況なら必ずこの技」という一覧ではありません。観察した問題に合わせて調整し、結果をもう一度読む循環です。比較した内容を、最後に一つの縦の判断順序へ戻します。</p>\n          <ol class=\"fundamentals-path logic-flow offensive-decision-flow\">\n            <li><span>01</span><div><h3>攻撃位置を読む</h3><p>Range・Angles・Closureと、使えるTurning Roomを確認します。</p></div></li>\n            <li><span>02</span><div><h3>入口を選ぶ</h3><p>Turn Circleへ早すぎず遅すぎず、RACを管理できる時点で入ります。</p></div></li>\n            <li><span>03</span><div><h3>問題を調整する</h3><p>Closure過多ならHigh側、距離過多ならLow側など、問題に合う調整を選びます。</p></div></li>\n            <li><span>04</span><div><h3>相手の変化を読む</h3><p>Redefinitionが起きたら、以前の追跡を捨てて関係を読み直します。</p></div></li>\n            <li><span>05</span><div><h3>中立化を認識する</h3><p>明確な後方優位が失われたら、以前の攻撃関係を前提にしません。High-Aspect BFMとして新しいFlowを読みます。</p></div></li>\n            <li><span>06</span><div><h3>位置確認へ戻る</h3><p>新しいRange・Angles・Closureと相対Energyを読みます。次の判断は、更新された関係から始めます。</p></div></li>\n          </ol>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">REVIEW MAP</p>\n            <h3>迷った項目だけ戻る</h3>\n            <div class=\"comparison-cards three-up card-grid review-map\">\n              <article class=\"content-card\"><h3>位置が読めない</h3><p>Aspect・ATA・RACを<a href=\"#offensive-geometry\">Mission 02</a>で確認します。</p></article>\n              <article class=\"content-card\"><h3>距離調整が曖昧</h3><p>EntryとYo-Yoを<a href=\"#offensive-entry\">Mission 03</a>・<a href=\"#offensive-yoyos\">04</a>で比較します。</p></article>\n              <article class=\"content-card\"><h3>役割が変わった</h3><p>Overshoot・Response・High-Aspectを<a href=\"#offensive-overshoot\">Mission 05</a>〜<a href=\"#high-aspect\">07</a>で読み直します。</p></article>\n            </div>\n          </div>\n          <div class=\"warning-box callout callout-warning\"><span>最後の確認</span><p>技名だけを言えても、使う理由を説明できなければ判断にはつながりません。「何が問題で、何を変え、次に何を再確認するか」を一続きで説明します。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>Part 2の要点</strong><p>攻撃位置を読む、Entryを選ぶ、RACを調整する、相手の変化を読む、中立化を認識する——この流れを繰り返します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence part-two-mission\" id=\"offensive-quiz\" data-section=\"Offensive BFM確認問題\" aria-labelledby=\"offensive-quiz-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>09</span></p>\n              <p class=\"mission-reveal-title\">確認問題</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"offensive-quiz-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"offensive-quiz-title\"><span class=\"module-title-number lesson-number\">09:</span><span class=\"module-title-text lesson-title-text\">確認問題</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>技名ではなく、観察した問題と選択理由の対応を確かめる。</p>\n          </header>\n          <div class=\"quiz-intro\">\n            <p>各問に回答すると、正解・正しい答え・短い解説・復習リンクが表示されます。</p>\n            <div><span>ANSWERED</span><strong id=\"offensive-quiz-answered\">0 / 8</strong></div>\n          </div>\n          <div id=\"offensive-quiz-list\" class=\"quiz-list\"></div>\n          <section class=\"quiz-result\" id=\"offensive-quiz-result\" hidden tabindex=\"-1\" aria-labelledby=\"offensive-quiz-result-title\">\n            <p class=\"section-code\">FINAL SCORE</p>\n            <h3 id=\"offensive-quiz-result-title\"><span id=\"offensive-quiz-score\">0</span> / 8</h3>\n            <p id=\"offensive-quiz-message\"></p>\n            <button class=\"button button-quiet\" id=\"offensive-quiz-reset\" type=\"button\">もう一度挑戦する</button>\n          </section>\n          <noscript><p class=\"warning-box callout callout-warning\">確認問題の自動採点にはJavaScriptが必要です。本文と各章の「ここまでの要点」はJavaScriptなしでも読めます。</p></noscript>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"offensive-references\" data-section=\"参考資料\" aria-labelledby=\"offensive-references-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>10</span></p>\n              <p class=\"mission-reveal-title\">参考資料・出典</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"offensive-references-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"offensive-references-title\"><span class=\"module-title-number lesson-number\">10:</span><span class=\"module-title-text lesson-title-text\">参考資料・出典</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>方針</span>Part 2で使った提供テキスト、公式資料、公開図版を確認する。</p>\n          </header>\n          <div class=\"source-notice callout callout-source\"><strong>資料の表示方針</strong><p>本文では小さな参照番号だけを表示し、書誌情報、原典、権利表示、外部リンクはこの章へまとめています。内容は初心者向けに要約し、機種固有の性能値や具体的な操作手順は一般化していません。</p></div>\n          <ol class=\"references-list\">\n            <li id=\"offensive-ref-1\"><span>USER-PROVIDED TRANSCRIPT</span><div><h3>Offensive BFM 解説文字起こし</h3><p>ユーザー提供の「ofensive bfm.txt」。Part 2の章立て、Lag Displacement Roll、Ditch Follow、Radius Defense Follow、High-Aspect BFMの相対Energy、Circle flow、上下選択の整理に使用しています。機種固有の数値・操作手順・武器操作は掲載せず、概念を公開中の公式資料と照合して一般化しています。元動画のURL、作者、公開日は提供テキスト内にないため記載していません。</p></div><time datetime=\"2026-08-04\">提供日：2026-08-04</time></li>\n            <li id=\"offensive-ref-2\"><span>OFFICIAL PUBLICATION</span><div><h3>U.S. Air Force — AETCTTP 11-1</h3><p>§4.14のOffensive BFM Objectivesを中心に、優位な位置からTurn Circle上へ進み、Energyを保ってControl Zoneから管理できる攻撃機会へ移る目的を確認。BFM Cross-check、RAC、LOSR、Turn Circle Entry、Overshoot、Reversal、Merge、High-Aspect BFMの判断関係も参照しています。T-38C／IFF固有の性能値と操作手順は一般化していません。</p><a href=\"https://static.e-publishing.af.mil/production/1/aetc/publication/aetcttp11-1/aetcttp11-1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">公式PDF <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-08-05\">参照日：2026-08-05</time></li>\n            <li id=\"offensive-ref-3\"><span>OFFICIAL CURRICULUM</span><div><h3>U.S. Navy, Chief of Naval Air Training — CNATRAINST 1542.167B</h3><p>Attack Window、Attack Window Entry、Fight Redefinition、Point of Departure、High-Aspect BFMの教育項目を確認。資料によって定義が変わる用語として説明し、機種・課程固有の角度、距離、手順は一般化していません。</p><a href=\"https://www.cnatra.navy.mil/local/docs/mcg/1542.167.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">公式PDF <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-08-04\">参照日：2026-08-04</time></li>\n            <li id=\"offensive-ref-4\"><span>PUBLIC DOMAIN IMAGES</span><div><h3>U.S. Navy, Naval Air Training Command — Offensive BFM diagrams</h3><p>CNATRA P-821、P-825、P-1289のHigh Yo-Yo、Low Yo-Yo、Rolling Scissors、Circle flow図。Wikimedia Commonsで米海軍の職務著作物・Public Domainと表示された画像を使用しています。米国国防総省による本サイトの推奨・承認を示すものではありません。</p><a href=\"https://commons.wikimedia.org/wiki/File:High_Yo-Yo_with_instruction_diagram.PNG\" target=\"_blank\" rel=\"noopener noreferrer\">High Yo-Yo <span aria-hidden=\"true\">↗</span></a> <a href=\"https://commons.wikimedia.org/wiki/File:Low_Yo-Yo_with_instruction_diagrams.PNG\" target=\"_blank\" rel=\"noopener noreferrer\">Low Yo-Yo <span aria-hidden=\"true\">↗</span></a> <a href=\"https://commons.wikimedia.org/wiki/File:Roller.png\" target=\"_blank\" rel=\"noopener noreferrer\">Rolling Scissors <span aria-hidden=\"true\">↗</span></a> <a href=\"https://commons.wikimedia.org/wiki/File:Circle_flow_in_air_combat.png\" target=\"_blank\" rel=\"noopener noreferrer\">Circle flow <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-08-04\">参照日：2026-08-04</time></li>\n          </ol>\n          <p class=\"citation-note\">Part 2の重要概念は、上記の公開資料と提供テキストを基に初心者向けに要約しています。実機の操作手順や武器運用は扱っていません。</p>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence part-two-mission\" id=\"defensive-next\" data-section=\"Next Part\" aria-labelledby=\"defensive-next-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>11</span></p>\n              <p class=\"mission-reveal-title\">Next Part</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"defensive-next-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"defensive-next-title\"><span class=\"module-title-number lesson-number\">11:</span><span class=\"module-title-text lesson-title-text\">Next Part</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>次の学習</span>Offensive BFMを振り返り、次のPartの公開状況を確認する。</p>\n          </header>\n          <div class=\"next-panel course-selector\">\n            <div class=\"course-completion\">\n              <p class=\"section-code\">PART 02 COMPLETE</p>\n              <h3>Offensive BFMを修了</h3>\n              <p>攻撃位置・Entry・Closure調整・Redefinition・High-Aspectへの移行を、一つの判断の流れとして確認しました。</p>\n            </div>\n            <div class=\"course-choice-grid card-grid\" aria-label=\"次の学習\">\n              <a class=\"course-choice content-card course-card\" href=\"#offensive-recap\">\n                <div class=\"course-choice-meta\"><span>REVIEW</span><span class=\"badge badge-live\">利用可能</span></div>\n                <h3>Part 2を復習する</h3>\n                <p>要点整理へ戻り、迷った項目だけを関連Missionで読み直します。</p>\n                <span class=\"button button-quiet\">要点へ戻る</span>\n              </a>\n              <article class=\"course-choice content-card course-card\" aria-disabled=\"true\">\n                <div class=\"course-choice-meta\"><span>COURSE 03</span><span class=\"badge\">準備中</span></div>\n                <h3>Defensive BFM</h3>\n                <p>不利な位置から攻撃機会を拒み、中立化や離脱へつなげる判断を学びます。</p>\n                <ul class=\"compact-list\"><li>脅威を読む</li><li>攻撃機会を拒む</li><li>役割の変化を判断する</li></ul>\n                <button class=\"button button-primary\" type=\"button\" disabled>公開準備中</button>\n              </article>\n            </div>\n            <p class=\"no-figure-note callout callout-status\"><span>COURSE STATUS</span>Part 3「Defensive BFM」は準備中です。</p>\n          </div>\n        </section>\n      </section>\n    </article>\n  </div>\n</main>\n\n<footer class=\"site-footer\">\n    <div class=\"footer-brand\"><span class=\"brand-mark\" aria-hidden=\"true\">B</span><div><strong>BFM Japan</strong><p>FLIGHT GEOMETRY FOR BEGINNERS</p></div></div>\n    <section class=\"footer-about\" id=\"site-background\" aria-labelledby=\"site-background-title\">\n      <div class=\"footer-about-heading\">\n        <p>ABOUT BFM JAPAN</p>\n        <h2 id=\"site-background-title\">このサイトについて</h2>\n      </div>\n      <p>このサイトは、製作者自身がBFMを学ぶ過程で、散在する用語や考え方を一つの流れに整理するためのまとめノートとして制作しました。同じようにBFMを学び始める人にも役立てばと思い公開しています。</p>\n    </section>\n    <div class=\"disclaimer\">\n      <h2>教育目的・ご利用上の注意</h2>\n      <ul>\n        <li>航空・フライトシミュレーターに関する教育用コンテンツであり、実際の軍事作戦や実機操縦訓練を目的としません。</li>\n        <li>公開情報を初心者向けに簡略化し、引用図には原典・作者・権利表示へのリンクを付けています。</li>\n        <li>性能は搭載物・重量・高度・速度・シミュレーターの版などで変わります。数値や図を絶対的なものとして扱わないでください。</li>\n        <li>武器に関する内容は、位置関係を理解するための教育用概念に限定しています。</li>\n      </ul>\n    </div>\n    <div class=\"footer-bottom\"><span>© 2026 BFM Japan</span><a href=\"#top\">PAGE TOP ↑</a></div>\n  </footer>";
